def test_dedupe_transcripts_keeps_last_duplicate_id_and_sorts():
    old = {"id": "a", "day": 0, "flagged": True}
    middle = {"id": "a", "day": 10, "flagged": True}
    latest = {"id": "a", "day": 3, "flagged": False}
    b = {"id": "b", "day": 3, "flagged": True}
    c = {"id": "c", "day": 1, "flagged": None}
    events = [old, b, middle, c, latest]
    assert dedupe_transcripts(events) == [c, latest, b]
    assert events == [old, b, middle, c, latest]
    assert dedupe_transcripts([]) == []


def test_daily_flag_counts_inclusive_range_and_gaps():
    events = [
        {"day": 0, "flagged": True},
        {"day": 1, "flagged": True},
        {"day": 1, "flagged": True},
        {"day": 2, "flagged": False},
        {"day": 2, "flagged": None},
        {"day": 4, "flagged": True},
        {"day": 5, "flagged": True},
    ]
    assert daily_flag_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_flag_counts(events, 1, 1) == [2]
    assert daily_flag_counts(events, 4, 1) == []
    assert daily_flag_counts([], -1, 1) == [0, 0, 0]


