def test_top_flagged_groups_order_ties_and_empty_groups():
    groups = {
        "z": [{"flagged": True}, {"flagged": False}],
        "empty": [],
        "a": [{"flagged": True}, {"flagged": None}],
        "best": [{"flagged": True}],
        "zero": [{"flagged": False}],
    }
    assert top_flagged_groups(groups, 3) == ["best", "a", "z"]
    assert top_flagged_groups(groups, 10) == ["best", "a", "z", "zero"]
    assert top_flagged_groups(groups, 0) == []
    assert top_flagged_groups({"empty": []}, 3) == []
    assert top_flagged_groups({}, 3) == []


def test_flag_rate_by_group_sorted_keys_and_empty_group():
    groups = {
        "z": [{"flagged": True}, {"flagged": None}],
        "empty": [],
        "a": [{"flagged": False}],
    }
    rates = flag_rate_by_group(groups)
    assert rates == {"a": 0.0, "empty": None, "z": 0.5}
    assert list(rates) == ["a", "empty", "z"]
    assert flag_rate_by_group({}) == {}


